INSERT INTO `raw_contents` VALUES (1, 1, NULL, 'jombang_post_1', 'Slamet Riyadi (Warga Ploso)', 'Jalan Poros Ploso-Kabuh Rusak Berlubang Parah', 'Ruas jalan poros Kecamatan Ploso menuju Kabuh rusak parah berlubang bgt dalan ajur, membahayakan pengendara motor truk industri sering melintas. Mohon dinas PUPR Jombang segera aspal perbaiki!', 'ruas jalan poros kecamatan ploso menuju kabuh rusak parah berlubang bgt dalan ajur, membahayakan pengendara motor truk industri sering melintas. mohon dinas pupr jombang segera aspal perbaiki!', 'https://radarjombang.jawapos.com/berita/1', '77dd3a9a20aca385293058d6b1662ae6e48edacdbf6c1165145133574a1d8191', NULL, 0, 'local_pemkab', NULL, '2026-11-16 01:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (2, 1, NULL, 'jombang_post_2', 'Hj. Mahmudah', 'Apresiasi Akses Jembatan Ploso Baru', 'Alhamdulillah sejak ada jembatan ploso baru mobilitas warga dari tembelang ke ploso lancar sekali tidak macet lagi, terima kasih pemkab jombang mantap apik tenan!', 'alhamdulillah sejak ada jembatan ploso baru mobilitas warga dari tembelang ke ploso lancar sekali tidak macet lagi, terima kasih pemkab jombang mantap apik tenan!', 'https://radarjombang.jawapos.com/berita/2', 'c5ecf8a374f4b4d428b2bc38f8485298b88ef8c179e865756a649c1de4ea47c2', NULL, 0, 'local_pemkab', NULL, '2026-11-14 23:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (3, 1, NULL, 'jombang_post_3', 'Parno Subekti', 'Keluhan Debu Pabrik di Kawasan Industri Kabuh', 'Warga desa di Kecamatan Kabuh mengeluhkan debu truk proyek kawasan industri dan jalan tambal sulam yang rusak lagi, DLH Jombang mohon cek amdal pabrik.', 'warga desa di kecamatan kabuh mengeluhkan debu truk proyek kawasan industri dan jalan tambal sulam yang rusak lagi, dlh jombang mohon cek amdal pabrik.', 'https://radarjombang.jawapos.com/berita/3', 'f7fdf04b551aa805466c98e014ed9e435567109cea5d013cba180b30a0cafe15', NULL, 0, 'local_pemkab', NULL, '2026-11-14 00:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (4, 1, NULL, 'jombang_post_4', 'Kusnan (Relawan Warga)', 'Tanggul Afvour Besuk Kali Konto Rembes', 'Hujan lebat debit air Kali Konto naik, warga Kecamatan Bandar Kedungmulyo was-was tanggul afvour besuk rembes rawan jebol banjir lagi. BPBD Jombang dan PUPR tolong kirim bronjong darurat!', 'hujan lebat debit air kali konto naik, warga kecamatan bandar kedungmulyo was-was tanggul afvour besuk rembes rawan jebol banjir lagi. bpbd jombang dan pupr tolong kirim bronjong darurat!', 'https://radarjombang.jawapos.com/berita/4', '7cbeed944c733d8648f9bd312283d69af90ef7fbb4f9b952ecf447fdb453c8be', NULL, 0, 'local_pemkab', NULL, '2026-11-15 20:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (5, 1, NULL, 'jombang_post_5', 'Imron Rosyadi', 'Normalisasi Sungai Kali Gunting Mojoagung', 'Pengerukan sedimentasi dan normalisasi sungai Kali Gunting di Kecamatan Mojoagung mulai berjalan baik, semoga musim hujan kali ini tidak langganan banjir lagi suwun pemkab.', 'pengerukan sedimentasi dan normalisasi sungai kali gunting di kecamatan mojoagung mulai berjalan baik, semoga musim hujan kali ini tidak langganan banjir lagi suwun pemkab.', 'https://radarjombang.jawapos.com/berita/5', 'aed308ef8ad11ffb7b3062c73e49562c3d02b798927f9d3aebfa7bb2e473bcfb', NULL, 0, 'local_pemkab', NULL, '2026-11-15 02:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (6, 1, NULL, 'jombang_post_6', 'Gus Wahid', 'Haul Masyayikh Tebuireng Berjalan Tertib', 'Rangkaian peringatan Haul Gus Dur di Pesantren Tebuireng Kecamatan Diwek berlangsung khidmat dan tertib. Rekayasa lalin Dishub Jombang sangat membantu kenyamanan peziarah.', 'rangkaian peringatan haul gus dur di pesantren tebuireng kecamatan diwek berlangsung khidmat dan tertib. rekayasa lalin dishub jombang sangat membantu kenyamanan peziarah.', 'https://radarjombang.jawapos.com/berita/6', 'ba3a583ad850490d8856c085b06dbc9bde30a81784913f2dcbc6c54df4fa0f4b', NULL, 0, 'local_pemkab', NULL, '2026-11-15 17:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
INSERT INTO `raw_contents` VALUES (7, 1, NULL, 'jombang_post_7', 'Santri Tambakberas', 'Apresiasi Beasiswa Santri Berprestasi Jombang', 'Alhamdulillah program beasiswa santri berprestasi dari Bagian Kesra Pemkab Jombang sangat membantu kawan-kawan pondok pesantren di Tambakberas dan Denanyar melanjutkan kuliah.', 'alhamdulillah program beasiswa santri berprestasi dari bagian kesra pemkab jombang sangat membantu kawan-kawan pondok pesantren di tambakberas dan denanyar melanjutkan kuliah.', 'https://radarjombang.jawapos.com/berita/7', '04d03c9125d12bd728f997a51605dc3befb669dcceda8330bfb97a9d7ac746e1', NULL, 0, 'local_pemkab', NULL, '2026-11-13 17:58:25', NULL, 1, 0, NULL, '2026-11-16 03:58:25', '2026-11-16 03:58:25');
