  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `sources_code_unique`(`code` ASC) USING BTREE,
  INDEX `sources_is_active_index`(`is_active` ASC) USING BTREE,
  INDEX `sources_platform_type_index`(`platform_type` ASC) USING BTREE,
  INDEX `sources_tier_index`(`tier` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

