-- ----------------------------
-- Table structure for sync_jobs
-- ----------------------------
DROP TABLE IF EXISTS `sync_jobs`;
CREATE TABLE `sync_jobs`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `job_uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_id` bigint UNSIGNED NULL DEFAULT NULL,
  `endpoint_id` bigint UNSIGNED NULL DEFAULT NULL,
  `status` enum('pending','running','completed','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `triggered_by` enum('system_cron','manual_user') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system_cron',
  `start_date` date NULL DEFAULT NULL,
  `end_date` date NULL DEFAULT NULL,
  `max_items_limit` int NOT NULL DEFAULT 50,
  `items_scraped` int NOT NULL DEFAULT 0,
  `items_processed` int NOT NULL DEFAULT 0,
  `log_messages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `sync_jobs_source_id_foreign`(`source_id` ASC) USING BTREE,
  INDEX `sync_jobs_endpoint_id_foreign`(`endpoint_id` ASC) USING BTREE,
  INDEX `sync_jobs_status_index`(`status` ASC) USING BTREE,
  INDEX `sync_jobs_job_uuid_index`(`job_uuid` ASC) USING BTREE,
  CONSTRAINT `sync_jobs_endpoint_id_foreign` FOREIGN KEY (`endpoint_id`) REFERENCES `source_endpoints` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `sync_jobs_source_id_foreign` FOREIGN KEY (`source_id`) REFERENCES `sources` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

